from __future__ import annotations

from typing import Any
import pytest

from llm_router._internal.providers.retry import (
    RetryPolicy,
    build_provider_async_retrying,
    is_retryable_provider_error,
)

pytestmark = pytest.mark.verification_kind("unit")


class _DummyRetryLogger:
    """Null logger accepting any logging or callable notification interface."""

    def __call__(self, *args: Any, **kwargs: Any) -> None:
        pass

    def warning(self, *args: Any, **kwargs: Any) -> None:
        pass

    def info(self, *args: Any, **kwargs: Any) -> None:
        pass

    def debug(self, *args: Any, **kwargs: Any) -> None:
        pass

    def log(self, *args: Any, **kwargs: Any) -> None:
        pass


def _create_retryable_error() -> Exception:
    """Produce an error instance that is accepted by is_retryable_provider_error."""
    globs = getattr(is_retryable_provider_error, "__globals__", {})
    co_names = getattr(getattr(is_retryable_provider_error, "__code__", None), "co_names", ())

    candidate_classes: list[type[BaseException]] = []
    for name in co_names:
        obj = globs.get(name)
        if isinstance(obj, type) and issubclass(obj, BaseException):
            candidate_classes.append(obj)
    for obj in globs.values():
        if isinstance(obj, type) and issubclass(obj, BaseException) and obj not in candidate_classes:
            candidate_classes.append(obj)

    for cls in candidate_classes:
        for kwargs in (
            {},
            {"retryable": True},
            {"status_code": 429},
            {"status_code": 503},
            {"message": "rate limit", "status_code": 429},
            {"message": "rate limit", "retryable": True},
        ):
            try:
                inst = cls(**kwargs)
                if is_retryable_provider_error(inst):
                    return inst
            except Exception:
                pass

        try:
            inst = cls("temporary provider failure")
            for attr, val in (("retryable", True), ("is_retryable", True), ("status_code", 429)):
                try:
                    setattr(inst, attr, val)
                except Exception:
                    pass
            if is_retryable_provider_error(inst):
                return inst
        except Exception:
            pass

    for base in candidate_classes or [Exception]:
        try:
            class _SyntheticRetryableError(base):  # type: ignore[valid-type, misc]
                retryable = True
                is_retryable = True
                status_code = 429

            inst = _SyntheticRetryableError("temporary provider failure")
            if is_retryable_provider_error(inst):
                return inst
        except Exception:
            pass

    fallback = Exception("temporary provider failure")
    setattr(fallback, "retryable", True)
    setattr(fallback, "is_retryable", True)
    setattr(fallback, "status_code", 429)
    return fallback


@pytest.mark.anyio
@pytest.mark.asyncio
@pytest.mark.verifies("TREQ_PROVIDER_RETRY_BOUNDS[revision==1]")
async def test_provider_async_retrying_exhaustion_reraises_provider_error() -> None:
    max_attempts = 3
    policy = RetryPolicy(
        min_wait_seconds=0.001,
        max_wait_seconds=0.002,
        max_attempts=max_attempts,
    )
    retrying = build_provider_async_retrying(
        policy=policy,
        logger=_DummyRetryLogger(),
        context_getter=None,
        state_sink=None,
    )

    retryable_error = _create_retryable_error()
    assert is_retryable_provider_error(retryable_error) is True

    attempt_count = 0

    async def flaky_provider_call() -> None:
        nonlocal attempt_count
        attempt_count += 1
        raise retryable_error

    with pytest.raises(BaseException) as exc_info:
        await retrying(flaky_provider_call)

    assert attempt_count == max_attempts
    assert exc_info.value is retryable_error
    assert type(exc_info.value).__name__ != "RetryError"
